       WHERE schemaname=current_schema() AND indexname='directory_sources_tenant_unique'
         AND indexdef NOT LIKE '%WHERE (status = ''active''::text)%'
     ) THEN
       DROP INDEX directory_sources_tenant_unique;
     END IF;
     IF NOT EXISTS (
       SELECT 1 FROM pg_indexes
       WHERE schemaname=current_schema() AND indexname='directory_sources_tenant_unique'
     ) THEN
